"""Optimal allocation for multi-level baby-step/giant-step search (partition lemma)."""
from __future__ import annotations

import math
from typing import List, Sequence, Tuple


def level_cost(L: float, T: float, S: float) -> float:
    if L * T < S - 1e-9 * max(1.0, S):
        raise ValueError("level does not cover its share: need L*T >= S")
    return L + T


def best_cost_for_shares(shares: Sequence[float]) -> Tuple[float, List[Tuple[float, float]]]:
    """Minimum of sum(L_i + T_i) subject to L_i T_i >= S_i: each level balanced at sqrt(S_i)."""
    plan = [(math.sqrt(s), math.sqrt(s)) for s in shares]
    return sum(2 * math.sqrt(s) for s in shares), plan


def partition_bound(shares: Sequence[float]) -> float:
    """Partition lemma lower bound 2 sqrt(S)."""
    return 2 * math.sqrt(sum(shares))


def strict_gap(shares: Sequence[float]) -> float:
    """(best cost)^2 - (2 sqrt S)^2 = 8 * sum_{i<j} sqrt(S_i S_j) > 0 iff >= 2 active levels."""
    r = [math.sqrt(s) for s in shares]
    return 8 * sum(r[i] * r[j] for i in range(len(r)) for j in range(i + 1, len(r)))


if __name__ == "__main__":
    S = 1e6
    for shares in ([S], [S / 2, S / 2], [0.9 * S, 0.1 * S], [S / 4] * 4, [S / 9] * 9):
        best, _ = best_cost_for_shares(shares)
        lb = partition_bound(shares)
        print(f"{len(shares)} levels: best {best:9.2f}  bound {lb:8.2f}  ratio {best / lb:.4f}"
              f"  squared gap {strict_gap(shares):.1f}")
